def _history_records(curve: pd.DataFrame, start: pd.Timestamp, end: pd.Timestamp) -> pd.DataFrame:
    subset = _slice_curve(curve, start, end)
    if subset.empty:
        return subset
    exposure = pd.to_numeric(subset["gross_exposure"], errors="coerce").fillna(0.0)
    full_exposure = pd.to_numeric(curve["gross_exposure"], errors="coerce").fillna(0.0)
    prev_full = full_exposure.shift(1).reindex(subset.index).fillna(0.0)
    changed = (exposure - prev_full).abs() > 1e-9
    records = subset.loc[changed].copy()
    if not records.empty:
        records["prev_exposure"] = prev_full.loc[records.index]
    return records


def render_signal_history(query: str) -> str:
    curves = load_strategy_curves()
    shared_index = pd.DatetimeIndex(sorted(set.union(*(set(df.index) for df in curves.values()))))
    start, end, label = parse_date_range(query, shared_index)
    lines = ["## 信号历史 / 交易记录", "", f"- 查询区间: **{label}** ({start:%Y-%m-%d} 至 {end:%Y-%m-%d})", "- 定义: final gross_exposure 相比上一交易日发生实质变化。", ""]
    for config in STRATEGIES:
        records = _history_records(curves[config.key], start, end)
        lines.extend([f"### {config.display_name}", "| 日期 | 前敞口 | 后敞口 | Score | 说明 |", "|:-|------:|------:|------:|:-|"])
        if records.empty:
            lines.append("| - | - | - | - | 区间内无敞口变化 |")
        else:
            tail = records.tail(30)
            for idx, row in tail.iterrows():
                lines.append(
                    f"| {idx:%Y-%m-%d} | {pct(row.get('prev_exposure'), 1)} | {pct(row.get('gross_exposure'), 1)} | "
                    f"{num(row.get('score'), 3)} | {_overlay_summary(row)} |"
                )
            if len(records) > len(tail):
                lines.append(f"| ... | ... | ... | ... | 仅显示最近{len(tail)}条，共{len(records)}条 |")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def render_nav_chart(query: str, combo: bool = False) -> str:
    curves = load_strategy_curves()
    source = build_combo_curves(curves) if combo else curves
    order = (
        [
            ("zz1000_hs300_pair50", "ZZ1000/HS300 50/50"),
            ("cyb_hs300_pair50", "CYB/HS300 50/50"),
            ("zz1000_sz50_pair50", "ZZ1000/SZ50 50/50"),
            ("three_pair_equal_weight", "Total 1/3"),
        ]
        if combo
        else [(config.key, config.direction_en) for config in STRATEGIES]
    )
    if not combo:
        combos = build_combo_curves(curves)
        source = dict(source)
        source["three_pair_equal_weight"] = combos["three_pair_equal_weight"]
        order = list(order) + [("three_pair_equal_weight", "Total 1/3")]
    index_sets = [set(source[k].index) for k, _ in order]
    if combo:
        shared_index = pd.DatetimeIndex(sorted(set.intersection(*index_sets)))
    else:
        shared_index = pd.DatetimeIndex(sorted(set.union(*index_sets)))
    start, end, label = parse_date_range(query, shared_index)
    try:
        import matplotlib.pyplot as plt

        fig, ax = plt.subplots(figsize=(10, 7))
        for key, display in order:
            subset = _slice_curve(source[key], start, end)
            if subset.empty:
                continue
            nav = _nav_from_returns(subset["return"])
            is_total = key == "three_pair_equal_weight"
            ax.plot(
                nav.index,
                nav / nav.iloc[0],
                label=display,
                color="#111111" if is_total else None,
                linewidth=3.2 if is_total else 1.4,
                alpha=1.0 if is_total else 0.78,
                zorder=10 if is_total else 3,
            )
        ax.set_title(f"{'Combo' if combo else 'Sleeve'} NAV - {start:%Y-%m-%d} to {end:%Y-%m-%d}")
        ax.set_ylabel("NAV, rebased to 1.0")
        ax.axhline(y=1.0, color="gray", linestyle="--", linewidth=0.8, alpha=0.5)
        ax.legend(fontsize=8)
        ax.grid(True, alpha=0.3)
        fig.tight_layout()
        chart_dir = OUTPUT_DIR / "poe_charts"
        chart_dir.mkdir(parents=True, exist_ok=True)
        path = chart_dir / f"adk_six_spread_{'combo' if combo else 'single'}_{start:%Y%m%d}_{end:%Y%m%d}.png"
        fig.savefig(path, dpi=150)
        plt.close(fig)
        return f"## 净值曲线\n\n- 查询区间: **{label}** ({start:%Y-%m-%d} 至 {end:%Y-%m-%d})\n- 图表文件: `{path}`\n"
    except Exception as exc:
        rows = []
        for key, display in order:
            rows.append((display, metrics_for_curve(_slice_curve(source[key], start, end))))
        return "## 净值曲线\n\n图表生成失败，返回同区间指标表。\n\n" + "\n".join(_metric_table(rows)) + f"\n\n错误: `{exc}`\n"


def _performance_chart_mode(query: str, rendered: Optional[str] = None) -> Optional[bool]:
    if rendered:
        if "50/50" in rendered and "1/3" in rendered:
            return True
        if "ADK" in rendered:
            return False
    normalized = _normalize_query(query)
    compact = normalized.replace(" ", "")
    if "缁勫悎琛ㄧ幇" in compact:
        return True
    if "琛ㄧ幇" in compact:
        return False
    return None


def _query_has_any(query: str, *terms: str) -> bool:
    return any(term and term in query for term in terms)


def _direct_nav_chart_mode(query: str) -> Optional[bool]:
    normalized = _normalize_query(query)
    compact = normalized.replace(" ", "")
    original = str(query).replace(" ", "")
    search = f"{original} {compact}"
    has_nav = _query_has_any(search, "\u51c0\u503c", "NAV", "nav", "鍑€鍊")
    has_chart = _query_has_any(search, "\u66f2\u7ebf", "\u56fe", "chart", "Chart", "鏇茬嚎", "鍥")
    if not (has_nav and has_chart):
        return None
    return _query_has_any(search, "\u7ec4\u5408", "combo", "Combo", "缁勫悎")


def _split_performance_rendered_for_chart(rendered: str) -> tuple[str, str]:
    lines = rendered.splitlines()
    table_start = next((idx for idx, line in enumerate(lines) if line.startswith("|")), None)
    if table_start is None:
        return rendered, ""
    before = "\n".join(lines[:table_start]).rstrip() + "\n\n"
    after = "\n".join(lines[table_start:]).rstrip() + "\n"
    return before, after


def _performance_nav_chart_payload(query: str, combo: bool) -> tuple[bytes, pd.Timestamp, pd.Timestamp]:
    curves = load_strategy_curves()
    source = build_combo_curves(curves) if combo else curves
    order = (
        [
            ("zz1000_hs300_pair50", "ZZ1000/HS300 50/50"),
            ("cyb_hs300_pair50", "CYB/HS300 50/50"),
            ("zz1000_sz50_pair50", "ZZ1000/SZ50 50/50"),
            ("three_pair_equal_weight", "Total 1/3"),
        ]
        if combo
        else [(config.key, config.direction_en) for config in STRATEGIES]
    )
    if not combo:
        combos = build_combo_curves(curves)
        source = dict(source)
        source["three_pair_equal_weight"] = combos["three_pair_equal_weight"]
        order = list(order) + [("three_pair_equal_weight", "Total 1/3")]
    index_sets = [set(source[k].index) for k, _ in order]
    if combo:
        shared_index = pd.DatetimeIndex(sorted(set.intersection(*index_sets)))
    else:
        shared_index = pd.DatetimeIndex(sorted(set.union(*index_sets)))
    start, end, _label = parse_date_range(query, shared_index)

    import matplotlib

    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.dates as mdates

    fig, ax = plt.subplots(figsize=(12, 8))
    plotted = 0
    colors = [
        "#E74C3C",
        "#9B59B6",
        "#2980B9",
        "#F39C12",
        "#27AE60",
        "#34495E",
        "#16A085",
        "#D35400",
    ]
    for key, display in order:
        subset = _slice_curve(source[key], start, end)
        if subset.empty:
            continue
        nav = _nav_from_returns(subset["return"])
        if nav.empty:
            continue
        nav = nav / nav.iloc[0]
        is_total = key == "three_pair_equal_weight"
        color = "#111111" if is_total else colors[plotted % len(colors)]
        ax.plot(
            nav.index,
            nav,
            label=f"{display} ({(nav.iloc[-1] - 1.0) * 100:+.1f}%)",
            color=color,
            linewidth=3.4 if is_total else 1.6,
            alpha=1.0 if is_total else 0.78,
            zorder=10 if is_total else 3,
        )
        plotted += 1
    if plotted == 0:
        plt.close(fig)
        raise ValueError("no NAV data in selected range")
    ax.set_title(f"{'Combo' if combo else 'Sleeve'} NAV - {start:%Y-%m-%d} to {end:%Y-%m-%d}")
    ax.set_ylabel("NAV, rebased to 1.0")
    ax.axhline(y=1.0, color="gray", linestyle="--", linewidth=0.8, alpha=0.5)
    ax.legend(loc="best", fontsize=10, framealpha=0.9)
    ax.grid(True, alpha=0.3)
    ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y-%m"))
    fig.autofmt_xdate(rotation=30)
    fig.tight_layout()
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=150, bbox_inches="tight")
    plt.close(fig)
    return buf.getvalue(), start, end


def _attach_performance_nav_chart(msg, query: str, rendered: Optional[str] = None) -> None:
    combo = _performance_chart_mode(query, rendered)
    if combo is None:
        return
    _attach_nav_chart(msg, query, combo=combo, name_prefix="perf_nav")


def _attach_nav_chart(msg, query: str, combo: bool, name_prefix: str) -> None:
    try:
        chart_bytes, start, end = _performance_nav_chart_payload(query, combo=combo)
        msg.attach_file(
            name=f"{name_prefix}_{'combo' if combo else 'single'}_{start:%Y%m%d}_{end:%Y%m%d}.png",
            contents=chart_bytes,
            content_type="image/png",
            is_inline=True,
        )
    except Exception as exc:
        msg.write(f"\n\n鍑€鍊煎浘鐢熸垚澶辫触: `{exc}`\n")


def _write_direct_nav_chart_response(msg, query: str, combo: bool) -> None:
    title = "\u7ec4\u5408\u51c0\u503c\u66f2\u7ebf" if combo else "\u51c0\u503c\u66f2\u7ebf"
    msg.write(f"## {title}\n\n")
    _attach_nav_chart(msg, query, combo=combo, name_prefix="nav_chart")
    msg.write("\n")


def _write_query_response(msg, query: str) -> None:
    nav_combo = _direct_nav_chart_mode(query)
    if nav_combo is not None:
        _write_direct_nav_chart_response(msg, query, combo=nav_combo)
        return

    rendered = render_query(query)
    combo = _performance_chart_mode(query, rendered)
    if combo is None:
        msg.write(rendered)
        return
    before_chart, after_chart = _split_performance_rendered_for_chart(rendered)
    msg.write(before_chart)
    _attach_nav_chart(msg, query, combo=combo, name_prefix="perf_nav")
    if after_chart:
        msg.write("\n" + after_chart)


def render_query(query: str) -> str:
    normalized = _normalize_query(query)
    compact = normalized.replace(" ", "")
    if not compact:
        compact = "信号"

    if "组合" in compact and "净值" in compact:
        return render_nav_chart(normalized, combo=True)
    if "净值" in compact and ("曲线" in compact or "图" in compact):
        return render_nav_chart(normalized, combo=False)
    if "组合表现" in compact:
        return render_performance(normalized, combo=True)
    if "表现" in compact:
        return render_performance(normalized, combo=False)
    if "参数" in compact and "实时" in compact:
        return render_params(live=True)
    if "参数" in compact:
        return render_params(live=False)
    if "信号" in compact and ("历史" in compact or "记录" in compact or "的信号" in compact or re.search(r"20\d{2}", compact)):
        return render_signal_history(normalized)
    if "实时" in compact and "信号" in compact:
        return render_signal(live=True)
    return render_signal(live=False)


async def get_response(request):  # pragma: no cover - Poe runtime entrypoint
    query = getattr(request, "query", None) or getattr(request, "text", "")
    with poe.start_message() as msg:
        try:
            _write_query_response(msg, str(query))
        except Exception as exc:
            msg.write("## 查询失败\n\n")
            msg.write(f"`{exc}`\n")
        return msg


def main(argv: Optional[list[str]] = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    query = " ".join(argv).strip()
    if not query:
        query_obj = getattr(poe, "query", None)
        query = getattr(query_obj, "text", "") if query_obj is not None else ""
    query = str(query).strip() or "??"
    with poe.start_message() as msg:
        try:
            _write_query_response(msg, query)
        except Exception as exc:
            msg.write("## 鏌ヨ澶辫触\n\n")
            msg.write(f"`{exc}`\n")
    return 0


def run() -> int:
    query_obj = getattr(poe, "query", None)
    query = getattr(query_obj, "text", "") if query_obj is not None else ""
    query = str(query).strip() or "ΠΕΊΕ"
    with poe.start_message() as msg:
        try:
            _write_query_response(msg, query)
        except Exception as exc:
            msg.write("## 查询失败\n\n")
            msg.write(f"`{exc}`\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(run())
